examples.template:
VStack(spacing: 0) {
    ViewThatFits(in: .horizontal) {
    HStack(spacing: theme.spacing.space3) {
        HStack(spacing: theme.spacing.space2) {
            Text("R")
                .monarchTextStyle(.bodyStrong)
                .foregroundStyle(theme.colors.textDefault)
                .frame(width: 24, height: 24)
                .background(theme.colors.bgMuted, in: RoundedRectangle(cornerRadius: 6))
                .accessibilityHidden(true)
            Text({{product}})
                .monarchTextStyle(.label)
                .fixedSize()
                .accessibilityAddTraits(.isHeader)
        }
        MonarchTextField(
            {{search}},
            text: $query,
            prompt: {{search}},
            labelVisibility: .hidden,
            leading: { Image(systemName: "magnifyingglass").foregroundStyle(theme.colors.textMuted) },
            trailing: { EmptyView() }
        )
        .frame(minWidth: 150)
        MonarchNotificationsBell(unreadCount: 0) {}
            .accessibilityLabel({{notifications}})
        Menu {
            Section("Signed in as " + {{account.email}}) {
                Button("Profile and preferences", systemImage: "person.crop.circle") {}
                Button("Rook account", systemImage: "arrow.up.forward.square") {}
            }
            Button("Sign out", systemImage: "rectangle.portrait.and.arrow.right", role: .destructive) {}
        } label: {
            MonarchAvatar(image: nil, name: {{account.name}}, size: .sm, isDecorative: true)
                .monarchMinimumHitTarget()
        }
        .accessibilityLabel("Account: " + {{account.name}})
    }
    // Too narrow for the search field beside the name: the field takes its own line.
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        HStack(spacing: theme.spacing.space3) {
            HStack(spacing: theme.spacing.space2) {
                Text("R")
                    .monarchTextStyle(.bodyStrong)
                    .foregroundStyle(theme.colors.textDefault)
                    .frame(width: 24, height: 24)
                    .background(theme.colors.bgMuted, in: RoundedRectangle(cornerRadius: 6))
                    .accessibilityHidden(true)
                Text({{product}})
                    .monarchTextStyle(.label)
                    .fixedSize()
                    .accessibilityAddTraits(.isHeader)
            }
            Spacer(minLength: 0)
            MonarchNotificationsBell(unreadCount: 0) {}
                .accessibilityLabel({{notifications}})
            Menu {
                Section("Signed in as " + {{account.email}}) {
                    Button("Profile and preferences", systemImage: "person.crop.circle") {}
                    Button("Rook account", systemImage: "arrow.up.forward.square") {}
                }
                Button("Sign out", systemImage: "rectangle.portrait.and.arrow.right", role: .destructive) {}
            } label: {
                MonarchAvatar(image: nil, name: {{account.name}}, size: .sm, isDecorative: true)
                    .monarchMinimumHitTarget()
            }
            .accessibilityLabel("Account: " + {{account.name}})
        }
            MonarchTextField(
                {{search}},
                text: $query,
                prompt: {{search}},
                labelVisibility: .hidden,
                leading: { Image(systemName: "magnifyingglass").foregroundStyle(theme.colors.textMuted) },
                trailing: { EmptyView() }
            )
    }
    }
    .padding(.horizontal, theme.spacing.space4)
    .padding(.vertical, theme.spacing.space3)
    Divider()
}

